import{_ as r,J as s,b as n,e as i,a8 as l,f as p,L as t}from"./chunks/framework.C-MVLAPI.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Resamplers","entity":"GR32_Resamplers","kind":"Unit","summary":"Provides bitmap resampling, spatial interpolation kernels, super-sampling, discrete convolution, morphological filters, and block transfers.","date":1788304505000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Resamplers/index.md","filePath":"api/GR32_Resamplers/index.md","lastUpdated":1788304505000,"timestamp":1788304505000,"datetime":"2026-09-01T23:15:05.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),o={name:"api/GR32_Resamplers/index.md"};function m(c,e,R,T,d,f){const a=s("ApiMembers");return n(),i("div",null,[e[0]||(e[0]=l('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_Resamplers</code> unit implements high-performance image resampling, spatial filtering, neighborhood sampling, and block transfer operations in Graphics32.</p><p>It includes:</p><ul><li><strong>Resamplers</strong>: Fast nearest-neighbor (<a href="/api/GR32_Resamplers/TNearestResampler/">TNearestResampler</a>), bilinear (<a href="/api/GR32_Resamplers/TLinearResampler/">TLinearResampler</a>), draft downscaling (<a href="/api/GR32_Resamplers/TDraftResampler/">TDraftResampler</a>), and high-quality arbitrary kernel resampling (<a href="/api/GR32_Resamplers/TKernelResampler/">TKernelResampler</a>).</li><li><strong>Spatial Reconstruction Kernels</strong>: A comprehensive collection of filter kernels including Box (<a href="/api/GR32_Resamplers/TBoxKernel/">TBoxKernel</a>), Triangle/Linear (<a href="/api/GR32_Resamplers/TLinearKernel/">TLinearKernel</a>), Cosine (<a href="/api/GR32_Resamplers/TCosineKernel/">TCosineKernel</a>), B-Spline (<a href="/api/GR32_Resamplers/TSplineKernel/">TSplineKernel</a>), Mitchell-Netravali (<a href="/api/GR32_Resamplers/TMitchellKernel/">TMitchellKernel</a>), Keys Cubic (<a href="/api/GR32_Resamplers/TCubicKernel/">TCubicKernel</a>), Hermite (<a href="/api/GR32_Resamplers/THermiteKernel/">THermiteKernel</a>), Sinsh (<a href="/api/GR32_Resamplers/TSinshKernel/">TSinshKernel</a>), Gaussian (<a href="/api/GR32_Resamplers/TGaussianKernel/">TGaussianKernel</a>), and Windowed-Sinc kernels (<a href="/api/GR32_Resamplers/TAlbrechtKernel/">TAlbrechtKernel</a>, <a href="/api/GR32_Resamplers/TLanczosKernel/">TLanczosKernel</a>, <a href="/api/GR32_Resamplers/TBlackmanKernel/">TBlackmanKernel</a>, <a href="/api/GR32_Resamplers/THannKernel/">THannKernel</a>, <a href="/api/GR32_Resamplers/THammingKernel/">THammingKernel</a>).</li><li><strong>Nested Samplers &amp; Coordinate Transformers</strong>: Sampler chaining via <a href="/api/GR32_Resamplers/TNestedSampler/">TNestedSampler</a>, coordinate transformation via <a href="/api/GR32_Resamplers/TTransformer/">TTransformer</a>, uniform <a href="/api/GR32_Resamplers/TSuperSampler/">TSuperSampler</a>, and recursive adaptive <a href="/api/GR32_Resamplers/TAdaptiveSuperSampler/">TAdaptiveSuperSampler</a>.</li><li><strong>Neighborhood &amp; Morphological Samplers</strong>: Discrete convolution (<a href="/api/GR32_Resamplers/TConvolver/">TConvolver</a>), bilateral/selective convolution (<a href="/api/GR32_Resamplers/TSelectiveConvolver/">TSelectiveConvolver</a>), morphological dilation (<a href="/api/GR32_Resamplers/TDilater/">TDilater</a>), erosion (<a href="/api/GR32_Resamplers/TEroder/">TEroder</a>), expansion (<a href="/api/GR32_Resamplers/TExpander/">TExpander</a>), and contraction (<a href="/api/GR32_Resamplers/TContracter/">TContracter</a>).</li><li><strong>Block Transfer Functions</strong>: High-performance unscaled (<a href="/api/GR32_Resamplers/BlockTransfer">BlockTransfer</a>, <code>BlockTransferX</code>, <a href="/api/GR32_Resamplers/BlendTransfer">BlendTransfer</a>) and scaled (<a href="/api/GR32_Resamplers/StretchTransfer">StretchTransfer</a>) bitmap transfer routines.</li></ul>',4)),p("p",null,[t(a,{type:"members"})])])}const G=r(o,[["render",m]]);export{_ as __pageData,G as default};
